/// Draw the app for a user who is entitled to see it.
export function renderAll() {
	trail('renderAll');
	step('Workers.load', function () { return Workers.load(); });
	step('PeerAgents.start', function () { return PeerAgents.start(); });
	// These two were called with no `await` and no `.catch`, so anything they
	// threw became an unhandled rejection -- which is exactly what the phone's
	// trail showed, twice per boot, from `opfs.rs` failing to open a path.
	step('Instructions.refresh', function () { return Instructions.refresh(); });
	step('Prompts.refresh', function () { return Prompts.refresh(); });
	renderSessionList();
	// THE CHAT THE READER WAS IN, not the first one the store enumerated.
	//
	// This was `chats.find(c => !c.diamondId)`, and `chats` comes back from
	// IndexedDB in key order — so a boot opened the OLDEST chat while the rail,
	// sorted newest-first, showed a different one at the top. On a phone, where
	// resuming the app is a boot, that reads as the transcript you were reading
	// having vanished; tapping its tile brings it straight back, because
	// nothing was ever lost. A daimon's record is skipped in both halves: it has
	// no tile, so opening one would put a conversation on screen that the rail
	// says does not exist.
	// THIS TAB's view, not the device's: see TAB_VIEW_KEY. Taken whole, now.
	var tv = tabViewGet();
	var want = tv.chat;
	// READ BEFORE `selectChat` BELOW, which clears it. The restore itself
	// cannot run until `loadDiamonds` has read the rail, and by then the
	// chat this boot opened has already forgotten the Diamond on the user's
	// behalf -- so a boot with any stored chat lost the Diamond every time,
	// and one with none did not. That is why it passed here and failed in
	// the gate: the fixture, not the feature.
	var wantDiamond = tv.diamond;
	var wantFace    = tv.face;
	var openChat = pg.chats.find(function (c) { return !c.diamondId && c.id === want; });
	// Failing that, the newest — which is the tile at the top of the rail, and
	// so the one somebody looking at the rail would expect to be reading.
	if (!openChat) {
		pg.chats.forEach(function (c) {
			if (c.diamondId) return;
			if (!openChat || (c.updatedAt || 0) > (openChat.updatedAt || 0)) openChat = c;
		});
	}
	if (openChat) { selectChat(openChat); } else { renderEmptyState(); }
	// The two defaults are offered only after the rail's own Diamonds are read
	// and any older root has been merged -- `list_diamonds` is what runs
	// `migrate_root` -- so the "only into an empty rail" rule is answered from
	// the store as it finally stands, not as it stood mid-migration.
	step('loadDiamonds', function () {
		return loadDiamonds().then(bootInherit, function (e) { bootInherit(); throw e; })
			.then(function () { return seedDefaultDiamonds(); })
			// AND THE SPARES ARE SWEPT, OUTSIDE THAT FLAG. The duplicates reported
			// live are on devices that seeded BEFORE the fixed ids landed, so
			// `seedDefaultDiamonds` returns on its flag at their first line and a
			// sweep inside it would never run on the one account that needs it.
			// `sweepSeededDuplicates` was written for exactly this and had no
			// caller but `DaimondDiamond.seedDefaults`, which the boot does not
			// take -- so the cure existed and no user could reach it. Measured
			// 2026-08-28: four records, four tiles, unchanged across a reload.
			.then(function () { return sweepSeededDuplicates(); })
			// Once per Diamond at start-up, the page-log rows an earlier sync's replace dropped (PLE).
			.then(function () { return healPageLogsAll().catch(function () { /* the next start-up tries again */ }); })
			.then(function () {
				// AFTER the rail is read, because a Diamond cannot be reopened
				// before it exists -- and after `selectChat` above, which it
				// deliberately overrides: the key is only set when a Diamond was
				// the last thing selected, and `selectChat` removes it.
				var wantF = wantDiamond;
				if (!wantF) return;
				var f = pg.diamonds.find(function (x) { return x.id === wantF; });
				// Gone, or trashed: fall back to the chat already on screen rather
				// than to an empty stage. `selectChat` above has already cleared the
				// Diamond from this tab's view, so it stops being asked.
				if (!f) return;
				// On the face THIS TAB left it on. The per-Diamond memory
				// (`diamondView`) is shared by every tab and answers only when the
				// tab recorded none. `selectDiamond` writes the Diamond back into the
				// view, which `selectChat` cleared on the way past -- so a second
				// reload finds it exactly as this one did.
				return selectDiamond(f, wantFace || undefined);
			});
	});
	// `load` marks every parked consent expired, because what a tile holds is a
	// promise and a promise does not survive the reload that just happened.
	step('Pending.load', function () {
		Pending.load(); Pending.render();
		runnerWatch();
		runnerPairWatch();
	});
	step('triggerClock', function () { startTriggerClock(); });
	step('expiryClock', function () { startExpiryClock(); });
	step('updateSpend', function () { updateSpend(); });
	step('panels.reflow', function () { DaimondPanels.reflow(); });
	if (!isMobile() && DaimondPanels.isOpen('work')) Files.onOpen();
	// A panel that was already open when the app booted is never `show`n,
	// so it would otherwise never ask the gateway what this account holds
	// and would sit there reporting the account service unreachable.
	if (window.DaimondMail && DaimondPanels.isOpen('mail')) { DaimondMail.onOpen(); }
	// And the Terminal, for the same reason: a panel left open in the saved
	// layout is never `show`n, so nothing would ever build the terminal into it.
	if (window.DaimondTerm && DaimondPanels.isOpen('term')) DaimondTerm.onOpen();
	if (window.DaimondTrashPanel && DaimondPanels.isOpen('trash')) DaimondTrashPanel.onOpen();
	if (window.DaimondSocial && DaimondPanels.isOpen('social')) { DaimondSocial.onOpen(); }
	// Expiry and retention, on every boot. A device that has been off for six
	// weeks comes back to a trash whose whole contents are due, and works
	// that out from the stamps it already holds rather than from a message
	// another device may no longer be sending. After the Diamonds are read,
	// because destroying one goes through the store this step opened — and
	// AFTER THE FIRST PULL, which is the whole of `sweepWhenTold`.
	step('trashSweep', function () { return sweepWhenTold(); });
	// A restore, or a trashing, in ANOTHER TAB — or in this one, or in a
	// parcel that has just arrived. None of them redraws these two lists on
	// its own: the chats fire a nonce this file already watches, but the
	// trash record is the thing that decides what those lists CONTAIN.
	//
	// Coalesced, because "Delete all chats" moves the record once per chat
	// and re-reading both stores fourteen times over would make the one act
	// this whole feature exists for the slowest thing in the app.
	var _trashRedraw = null;
	try {
		DaimondTrash.subscribe(function () {
			if (_trashRedraw) return;
			_trashRedraw = setTimeout(function () {
				_trashRedraw = null;
				onChatsChangedElsewhere();
				loadDiamonds();
				// And retention, here as well as at the boot: a desktop left
				// open for a month would otherwise never reach its own thirty
				// day mark. `trashSweep` refuses to run inside itself, so the
				// destruction it does — which moves the record — cannot start
				// another one.
				//
				// Not `expireChats` as well. A parcel that carries a fresher
				// `updatedAt` moves the trash record and lands here, and
				// re-expiring inside the callback the expiry itself woke would
				// be a loop looking for a reason to run. The hourly clock is
				// where that recheck belongs, and it is soon enough for a
				// window measured in days.
				trashSweep();
			}, 60);
		});
	} catch (e) { /* no trash module in this build */ }
	// Fold back whatever was in flight when the tab last died. Runs after Workers.load, so an
	// interrupted agent's record exists to enrich; repaints the affected chat and the panel.
	recoverInterrupted();
}
